'use client';
import React from 'react';

import * as Picker from 'emoji-picker-react/primitives';

// Docked chat-column picker: a short panel with tabs on top and a
// compact grid.
export type PickerExampleProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ComponentType<Picker.RootProps>;
  className?: string;
};

export function PickerExample({
  Root: RootComponent = Picker.Root,
  className,
}: PickerExampleProps) {
  return (
    <RootComponent
      appearance="default"
      className={className}
      searchPlaceholder="Search emotes and emoji"
      autoFocusSearch={false}
    >
      <Picker.CategoryNav />
      <Picker.Search />
      <Picker.Viewport>
        <Picker.List />
        <Picker.Empty />
      </Picker.Viewport>
    </RootComponent>
  );
}

/* Livestream chat — docked under the chat log: dark, full column width,
   tabs on top, short and dense. */
.stream-picker {
  --epr-bg-color: #1f1f23;
  --epr-text-color: #c8c8d0;
  --epr-highlight-color: #bf94ff;
  --epr-hover-bg-color: #2f2f35;
  --epr-focus-bg-color: #3d3d44;
  --epr-search-input-bg-color: #0e0e10;
  --epr-search-input-bg-color-active: #0e0e10;
  --epr-search-border-color: #3d3d44;
  --epr-search-border-color-active: #bf94ff;
  --epr-search-input-height: 30px;
  --epr-search-input-border-radius: 6px;
  --epr-search-input-text-color: #efeff1;
  --epr-search-input-placeholder-color: #a8a8b3;
  --epr-category-label-bg-color: #1f1f23f2;
  --epr-category-label-text-color: #c8c8d0;
  --epr-category-label-height: 26px;
  --epr-category-icon-active-color: #bf94ff;
  --epr-category-icon-inactive-color: #a8a8b3;
  --epr-category-navigation-button-size: 18px;
  --epr-emoji-variation-picker-bg-color: #2f2f35;
  --epr-emoji-size: 24px;
  --epr-emoji-padding: 4px;
  --epr-horizontal-padding: 10px;
  height: 230px;
  border-top: 1px solid #2f2f35;
  background: var(--epr-bg-color);
}
.stream-picker [data-epr-part='category-nav'] > * {
  padding: 8px 10px 4px;
}
.stream-picker [data-epr-part='category-tab'][aria-selected='true'] {
  box-shadow: 0 9px 0 -7px #bf94ff;
}
.stream-picker [data-epr-part='search'] > * {
  padding: 4px 10px;
}
.stream-picker [data-epr-part='category-label'] {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.stream-picker [data-epr-part='emoji'] {
  border-radius: 4px;
}

